Ah, I see we have a classic exercise in mathematical precision. The tests define the contract; our implementation must satisfy it exactly—no more, no less. As I have often said, premature generalization is as dangerous as premature optimization.

Let me construct the implementation with the rigor befitting a proper algorithm:

```go
package cart

// Item represents a product in the shopping cart
type Item struct {
	Name     string
	Price    float64
	Quantity int
}

// ShoppingCart holds items for purchase
type ShoppingCart struct {
	items []Item
}

// NewShoppingCart creates an empty cart
func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items: []Item{},
	}
}

// AddItem adds an item to the cart
func (c *ShoppingCart) AddItem(name string, price float64, quantity int) {
	for i, item := range c.items {
		if item.Name == name {
			c.items[i].Quantity += quantity
			return
		}
	}
	c.items = append(c.items, Item{Name: name, Price: price, Quantity: quantity})
}

// RemoveItem removes an item entirely from the cart
func (c *ShoppingCart) RemoveItem(name string) {
	for i, item := range c.items {
		if item.Name == name {
			c.items = append(c.items[:i], c.items[i+1:]...)
			return
		}
	}
}

// GetTotal calculates the sum of price * quantity for all items
func (c *ShoppingCart) GetTotal() float64 {
	var total float64
	for _, item := range c.items {
		total += item.Price * float64(item.Quantity)
	}
	return total
}

// GetItemCount returns the total quantity of all items
func (c *ShoppingCart) GetItemCount() int {
	count := 0
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}

// IsEmpty returns true if the cart contains no items
func (c *ShoppingCart) IsEmpty() bool {
	return len(c.items) == 0
}

// Clear removes all items from the cart
func (c *ShoppingCart) Clear() {
	c.items = []Item{}
}

// GetItem retrieves an item by name, returns nil if not found
func (c *ShoppingCart) GetItem(name string) *Item {
	for i := range c.items {
		if c.items[i].Name == name {
			return &c.items[i]
		}
	}
	return nil
}
```

